import { HeadContent, Scripts, createRootRoute } from "@tanstack/react-router";
import { Aurora, Button, GradientText } from "performative-ui";

import { paletteStyle, resolveAppearance } from "@/appearance";
import { TooltipProvider } from "@/components/ui/tooltip";
import { siteConfig } from "@/config";
import { resume } from "@/content/resume";
import appCss from "../styles.css?url";

const title = `${resume.name} · ${resume.headlines[0] ?? "Resume"}`;
const pageUrl = `${siteConfig.siteUrl}/`;
// Generated by `vp run og-image`; preview crawlers need an absolute URL.
const ogImage = `${siteConfig.siteUrl}/og-image.png`;
const [firstName, ...rest] = resume.name.split(/\s+/);
// On <html>, so the prerendered page and portals (the contact dialog) get the
// configured accent colours from the first paint.
const htmlStyle = paletteStyle(resolveAppearance(siteConfig.appearance).palette);

export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: "utf-8" },
      { name: "viewport", content: "width=device-width, initial-scale=1" },
      { title },
      { name: "description", content: resume.summary },
      { name: "theme-color", content: "#08080b" },
      ...(siteConfig.noindex ? [{ name: "robots", content: "noindex" }] : []),

      // Open Graph: LinkedIn, Slack, Discord, iMessage, Facebook…
      { property: "og:type", content: "profile" },
      { property: "profile:first_name", content: firstName },
      { property: "profile:last_name", content: rest.join(" ") },
      { property: "og:site_name", content: resume.name },
      { property: "og:title", content: title },
      { property: "og:description", content: resume.summary },
      { property: "og:url", content: pageUrl },
      { property: "og:image", content: ogImage },
      { property: "og:image:type", content: "image/png" },
      { property: "og:image:width", content: "1200" },
      { property: "og:image:height", content: "630" },
      { property: "og:image:alt", content: title },

      // X/Twitter reads title, description and image from the og: tags.
      { name: "twitter:card", content: "summary_large_image" },
      { name: "twitter:image:alt", content: title },
    ],
    links: [
      { rel: "canonical", href: pageUrl },
      { rel: "stylesheet", href: appCss },
      // Favicons live in /public and are generated by `pnpm favicons`.
      { rel: "icon", href: "/favicon.ico", sizes: "32x32" },
      { rel: "icon", href: "/favicon.svg", type: "image/svg+xml" },
      { rel: "apple-touch-icon", href: "/apple-touch-icon.png" },
      { rel: "manifest", href: "/site.webmanifest" },
    ],
  }),
  shellComponent: RootDocument,
  notFoundComponent: NotFound,
});

function RootDocument({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className="dark" style={htmlStyle}>
      <head>
        <HeadContent />
      </head>
      <body>
        <TooltipProvider delayDuration={150}>{children}</TooltipProvider>
        <Scripts />
      </body>
    </html>
  );
}

/**
 * Shown when the client-side router can't match a path. Direct requests for
 * unknown URLs never reach the app: Cloudflare answers them with
 * public/404.html and a real 404 status.
 */
function NotFound() {
  return (
    <main className="relative isolate grid min-h-screen place-items-center overflow-hidden px-4 text-center">
      <Aurora className="-z-10" />
      <div>
        <p className="font-mono text-xs tracking-[0.2em] text-muted-foreground uppercase">
          Error 404
        </p>
        <h1 className="mt-3 text-5xl font-bold tracking-tight sm:text-7xl">
          <GradientText>Page not found</GradientText>
        </h1>
        <p className="mx-auto mt-4 max-w-md text-lg text-muted-foreground">
          There's nothing at this address. The resume is on the home page.
        </p>
        <div className="mt-8">
          <Button as="a" href="/" variant="ghost" size="lg">
            ← Back to the resume
          </Button>
        </div>
      </div>
    </main>
  );
}
